function loanParseNum(s){
  var v=Number(String(s).replace(/[, ]/g,''));
  return isFinite(v)? v : NaN;
}
function loanSchedule(principal, ratePct, months){
  principal=loanParseNum(principal); ratePct=loanParseNum(ratePct); months=loanParseNum(months);
  if(!(principal>0)) return { error:'本金必须为正数' };
  if(!(ratePct>=0)) return { error:'利率不能为负' };
  if(!(months>=1 && months%1===0)) return { error:'期限须为正整数月' };
  var r=ratePct/100/12, schedule=[], balance=principal, totalInterest=0;
  var monthly = (r===0) ? principal/months : principal*r/(1-Math.pow(1+r,-months));
  monthly = Math.round(monthly*100)/100;
  for(var i=1;i<=months;i++){
    var interest=Math.round(balance*r*100)/100;
    var principalPaid=Math.round((monthly-interest)*100)/100;
    if(i===months){ principalPaid=Math.round(balance*100)/100; }
    balance=Math.round((balance-principalPaid)*100)/100;
    if(balance<0) balance=0;
    totalInterest+=interest;
    schedule.push({ month:i, payment:monthly, principalPaid:principalPaid, interestPaid:interest, balance:balance });
  }
  return { error:null, monthly:monthly, totalPay:Math.round((monthly*months)*100)/100,
    totalInterest:Math.round(totalInterest*100)/100, schedule:schedule };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { loanParseNum:loanParseNum, loanSchedule:loanSchedule };
}
if (typeof window !== 'undefined') {
  window.LoanForgePure = { loanParseNum:loanParseNum, loanSchedule:loanSchedule };
}
